// The vocabulary of Arch Studio's interpreter: EN / DE / FR / IT (+ Swiss spellings) → spec fields.
// Pure data. parse.js builds an index from ENTRIES once and does all the logic; nothing here is prompt-specific.
//
// An entry is [lang, 'form|form|multi word form', meaning]. Forms are folded (lower case, ä→ae, é→e, ß→ss; the
// plain-stripped spelling ä→a is indexed as well), hyphens and apostrophes split words, several words make a phrase.
// lang: en de fr it, or * (shared). Meaning keys (all optional):
//   el     element noun (a head-noun candidate)             cls   noun class seen by neighbouring modifiers
//   hs     head strength (default 2; roof 1: "dome roof" is a dome)
//   imp    [element, weight]: element implied when the text names none
//   set    spec fields set when the word is present         neg   spec fields set when the word is negated
//   ctx    {headKey: meaning} by the head element (key = element, group of GROUPS, or _)
//   mod    {nounClass: meaning} by the nearest noun the word modifies (checked before ctx)
//   ord    explicit order (classical orders: on any head)  os    order on order-bearing heads, style elsewhere
//   sty    style   mat   material   vag   order implied by a character word (lower priority than ord)
//   fl     true = "fluted"           cnt   count noun (field name)        rb  uncounted → ribbed
//   dim    dimension word (height width length depth diameter radius span pitch)
//   num    number word value         mul   multiplier word (hundred, dozen)
//   prep   chunk boundary type       negator   corr (correction marker)   most (superlative)
//   stop   function word             fill  known word without a field     place  context place/building word
//   oos    category of a non-element noun (building part place vehicle animal person furniture food object abstract missing)
//   land   landmark (a whole building alone; sets fields through ctx)   top   "on top of"
//   topEl  element implied by "on top of <this>"                        spireHint  pointy (roof → spire)
//   colOnly  order word valid only on columnar heads                   prio  priority of ctx-implied fields (2)

export const GROUPS = {
  ordh: ['column', 'pilaster', 'capital', 'base', 'pedestal', 'entablature', 'cornice', 'portico'],
  col: ['column', 'pilaster'],
  colx: ['column', 'pilaster', 'capital', 'base', 'pedestal'],
  arch: ['arch', 'arcade'],
  arcs: ['arch', 'arcade', 'window', 'door'],
  open: ['window', 'door'],
  dome: ['dome', 'cupola'],
  top: ['spire', 'dome', 'cupola', 'obelisk'],
  bal: ['balustrade', 'baluster'],
  ent: ['entablature', 'cornice', 'portico', 'pediment'],
  ped: ['pediment', 'window', 'door', 'portico'],
  vagh: ['column', 'pilaster', 'capital', 'base', 'pedestal', 'entablature', 'cornice', 'portico', 'arch', 'arcade', 'pediment'],
};

/** Fold a word or phrase for matching: lower case, umlauts → ae/oe/ue, ß → ss, other diacritics stripped. */
export function fold(s) {
  return String(s).toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/œ/g, 'oe').replace(/æ/g, 'ae')
    .normalize('NFD').replace(/[̀-ͯ]/g, '');
}
/** Plain fold (ä → a): the spelling of someone typing German without umlauts. */
export function foldPlain(s) {
  return String(s).toLowerCase().replace(/ß/g, 'ss').replace(/œ/g, 'oe').replace(/æ/g, 'ae')
    .normalize('NFD').replace(/[̀-ͯ]/g, '');
}

// shorthands
const set = (o) => ({ set: o });
const P2 = (o) => ({ set: o, prio: 2 });

